"""Read the small configuration subset that affects listing defaults."""
import ast
import os
import re


def _value(raw):
    raw = raw.split("#", 1)[0].strip()
    if not raw:
        return None
    if raw.startswith('"') or raw.startswith("'"):
        try:
            return ast.literal_eval(raw)
        except (ValueError, SyntaxError):
            return raw.strip('"\'')
    if raw.lower() in ('true', 'false'):
        return raw.lower() == 'true'
    if raw.startswith('[') and raw.endswith(']'):
        body = raw[1:-1].strip()
        if not body:
            return []
        vals = []
        for item in re.findall(r'''(?:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|[^,]+)''', body):
            v = _value(item.strip())
            if v is not None:
                vals.append(v)
        return vals
    try:
        return int(raw)
    except ValueError:
        try:
            return float(raw)
        except ValueError:
            return raw


def read_toml(path):
    result = {}
    try:
        with open(path, encoding='utf-8') as stream:
            lines = iter(stream)
            section = result
            for line in lines:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                m = re.fullmatch(r'\[([^]]+)\]', line)
                if m:
                    section = result
                    for part in m.group(1).split('.'):
                        section = section.setdefault(part, {})
                    continue
                if '=' not in line:
                    continue
                key, raw = line.split('=', 1)
                raw = raw.strip()
                if raw.startswith('[') and ']' not in raw:
                    chunks = [raw]
                    for more in lines:
                        chunks.append(more.strip())
                        if ']' in more:
                            break
                    raw = ' '.join(chunks)
                section[key.strip()] = _value(raw)
    except (OSError, UnicodeError):
        return {}
    return result


def _merge(base, overlay):
    for key, value in overlay.items():
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            _merge(base[key], value)
        else:
            base[key] = value
    return base


def config_for_listing():
    try:
        from configcmd import paths
        _, global_path = paths()
    except Exception:
        global_path = os.path.join(os.path.expanduser('~'), '.config', 'lla', 'config.toml')
    config = read_toml(global_path)
    directory = os.getcwd()
    while True:
        profile = os.path.join(directory, '.lla.toml')
        if os.path.isfile(profile):
            _merge(config, read_toml(profile))
            break
        parent = os.path.dirname(directory)
        if parent == directory:
            break
        directory = parent
    return config


def apply_listing_defaults(args, argv):
    cfg = config_for_listing()
    args.exclude_paths = cfg.get('exclude_paths', []) if isinstance(cfg.get('exclude_paths', []), list) else []
    sort = cfg.get('sort', {}) if isinstance(cfg.get('sort'), dict) else {}
    filt = cfg.get('filter', {}) if isinstance(cfg.get('filter'), dict) else {}
    fmts = cfg.get('formatters', {}) if isinstance(cfg.get('formatters'), dict) else {}
    has = lambda *opts: any(a in opts or any(a.startswith(o + '=') for o in opts if o.startswith('--')) for a in argv)

    if not has('-s', '--sort'):
        value = cfg.get('default_sort')
        if value in ('name', 'size', 'date'):
            args.sort = value
    if not has('--sort-dirs-first'):
        args.sort_dirs_first = bool(sort.get('dirs_first', args.sort_dirs_first))
    if not has('--sort-natural'):
        args.sort_natural = bool(sort.get('natural', args.sort_natural))
    if not has('--sort-case-sensitive'):
        args.sort_case_sensitive = bool(sort.get('case_sensitive', args.sort_case_sensitive))
    if not has('-c', '--case-sensitive'):
        args.case_sensitive = bool(filt.get('case_sensitive', args.case_sensitive))
    if not has('--no-dotfiles'):
        args.no_dotfiles = bool(filt.get('no_dotfiles', args.no_dotfiles))
    if not has('--respect-gitignore'):
        args.respect_gitignore = bool(filt.get('respect_gitignore', args.respect_gitignore))
    if not has('--include-dirs'):
        args.include_dirs = bool(cfg.get('include_dirs', args.include_dirs))
    if not has('--permission-format'):
        args.permission_format = cfg.get('permission_format', args.permission_format)
    if not has('--depth', '-d') and (args.tree or args.recursive):
        depth = cfg.get('default_depth')
        if isinstance(depth, int):
            args.depth = depth

    if not any(has(x) for x in ('-l', '--long', '-g', '--grid', '-G', '--git', '-t', '--tree', '-T', '--table', '-S', '--sizemap', '--timeline', '-R', '--recursive')):
        fmt = cfg.get('default_format', 'default')
        mapping = {'long': 'long', 'grid': 'grid', 'git': 'git', 'tree': 'tree', 'table': 'table', 'sizemap': 'sizemap', 'timeline': 'timeline', 'recursive': 'recursive'}
        name = mapping.get(fmt)
        if name:
            if name == 'recursive': args.recursive = True
            else: setattr(args, name, True)
    if args.long:
        long_cfg = fmts.get('long', {}) if isinstance(fmts.get('long'), dict) else {}
        if not has('--hide-group'):
            args.hide_group = bool(long_cfg.get('hide_group', args.hide_group))
        if not has('--relative-dates'):
            args.relative_dates = bool(long_cfg.get('relative_dates', args.relative_dates))
    if args.grid:
        grid_cfg = fmts.get('grid', {}) if isinstance(fmts.get('grid'), dict) else {}
        if not has('--grid-ignore'):
            args.grid_ignore = bool(grid_cfg.get('ignore_width', args.grid_ignore))
    return cfg

